36	
37	export type MoveOutcome =
38	  | { readonly ok: true; readonly state: GameState }
39	  | { readonly ok: false; readonly reason: MoveRejection };
40	
41	export const WINNING_LINES: readonly WinningLine[] = [
42	  [0, 1, 2],
43	  [3, 4, 5],
44	  [6, 7, 8],
45	  [0, 3, 6],
46	  [1, 4, 7],
47	  [2, 5, 8],
48	  [0, 4, 8],
49	  [2, 4, 6],
50	];
51	
52	const BOARD_SIZE = 9;
53	
54	/**
55	 * The module trusts the player ids it receives; callers must derive them from
56	 * a verified identity, never from client-supplied request fields.
57	 */
58	export function createGame(participants: {
59	  readonly X: PlayerId;
60	  readonly O: PlayerId;
61	}): GameState {
62	  if (participants.X === '' || participants.O === '' || participants.X === participants.O) {
63	    throw new RangeError('participants must be two distinct non-empty player ids');
64	  }
65	  return {
66	    board: Array<Cell>(BOARD_SIZE).fill(null),
67	    turn: 'X',
68	    participants: { X: participants.X, O: participants.O },
69	    result: null,
70	  };
71	}
72	
73	export function findWinningLine(
74	  board: Board,
75	): { readonly mark: Mark; readonly line: WinningLine } | null {
76	  for (const line of WINNING_LINES) {
77	    const mark = board[line[0]];
78	    if (mark !== null && mark !== undefined && board[line[1]] === mark && board[line[2]] === mark) {
79	      return { mark, line };
80	    }
81	  }
82	  return null;
83	}
84	
85	export function applyMove(state: GameState, move: Move): MoveOutcome {
86	  const { participants } = state;
87	  if (move.playerId !== participants.X && move.playerId !== participants.O) {
88	    return { ok: false, reason: 'not_a_participant' };
89	  }
90	  if (state.result !== null || state.turn === null) {
91	    return { ok: false, reason: 'game_finished' };
92	  }
93	  if (participants[state.turn] !== move.playerId) {
94	    return { ok: false, reason: 'not_your_turn' };
95	  }
96	  const { cell } = move;
97	  if (!Number.isInteger(cell) || cell < 0 || cell >= BOARD_SIZE) {
98	    return { ok: false, reason: 'invalid_cell' };
99	  }
100	  if (state.board[cell] !== null) {
101	    return { ok: false, reason: 'cell_occupied' };
102	  }
103	
104	  const mark = state.turn;
105	  const board = state.board.map((c, i): Cell => (i === cell ? mark : c));
106	  const win = findWinningLine(board);
107	
108	  if (win !== null) {
109	    return {
110	      ok: true,
111	      state: {
112	        board,
113	        turn: null,
114	        participants,
115	        result: {
116	          outcome: 'win',
117	          winner: win.mark,
118	          winnerId: participants[win.mark],
119	          line: win.line,
120	        },
121	      },
122	    };
123	  }
124	  if (!board.includes(null)) {
125	    return { ok: true, state: { board, turn: null, participants, result: { outcome: 'draw' } } };
126	  }
127	  return {
128	    ok: true,
129	    state: { board, turn: mark === 'X' ? 'O' : 'X', participants, result: null },
130	  };
131	}
132	
133	export function readAuthoritativeState(state: GameState): GameState {
134	  const result: GameResult | null =
135	    state.result === null
136	      ? null
137	      : state.result.outcome === 'win'
138	        ? Object.freeze({
139	            outcome: 'win',
140	            winner: state.result.winner,
141	            winnerId: state.result.winnerId,
142	            line: Object.freeze([...state.result.line]) as unknown as WinningLine,
143	          })
144	        : Object.freeze({ outcome: 'draw' });
145	  return Object.freeze({
146	    board: Object.freeze([...state.board]),
147	    turn: state.turn,
148	    participants: Object.freeze({ X: state.participants.X, O: state.participants.O }),
149	    result,
150	  });
151	}
